/bin/bash -lc "node --input-type=module <<'JS'
import {spawn} from 'node:child_process';
import {mkdtemp, rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {once} from 'node:events';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], {env: {...process.env, PORT: '18080', DB_PATH: join(directory, 'db.sqlite')}, detached: true, stdio: ['ignore','pipe','pipe']});
try {
  await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Startup timeout')), 5000);
    child.stdout.on('data', chunk => { if (String(chunk).includes('listening on port')) {clearTimeout(timer); resolve();} });
    child.once('error', reject);
  });
  const response = await fetch('http://127.0.0.1:18080/health');
  if (response.status "'!== 200) throw new Error('"'Health failed');
  console.log('npm start health:', await response.text());
  const page = await fetch('http://127.0.0.1:18080/');
  if (page.status "'!== 200 || !(await page.text()).includes('"'id=\"app\"')) throw new Error('Page failed');
  console.log('npm start page: passed');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, {recursive: true, force: true});
}
JS
npm test
node --check server.js
node --check public/app.js
git diff --check
git add package.json server.js public test README.md
git commit -m \"Implement persistent Workboard projects\"
git status --porcelain
git rev-parse HEAD"

